<?php
declare(strict_types=1);session_start();require dirname(__DIR__).'/config/config.php';require_sign_in();$actor=(int)$_SESSION['user_id'];$role=$_SESSION['role'];$id=filter_input(INPUT_GET,'id',FILTER_VALIDATE_INT);if(!$id||$id===$actor){http_response_code(403);exit('You cannot analyze your own account.');}$db=db();$q=$db->prepare('SELECT id,name,email,username,role,status,created_at FROM users WHERE id=?');$q->execute([$id]);$user=$q->fetch();if(!$user||$user['role']==='system_admin'){http_response_code(403);exit('This account cannot be analyzed.');}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if($role!=='system_admin'||$user['role']!=='sub_admin'){http_response_code(403);exit('Only a System Admin can activate or deactivate a Sub System Admin.');}$newStatus=$user['status']==='active'?'disabled':'active';$q=$db->prepare('UPDATE users SET status=? WHERE id=?');$q->execute([$newStatus,$id]);$q=$db->prepare('INSERT INTO audit_logs(actor_id,action,entity_type,entity_id,details) VALUES(?,?,?,?,?)');$q->execute([$actor,$newStatus==='active'?'activate_role':'deactivate_role','user',$id,json_encode(['role'=>'sub_admin','status'=>$newStatus])]);header('Location: team_analyze.php?id='.$id.'&status_changed=1');exit;}if(!in_array($role,['system_admin','sub_admin'],true)){$q=$db->prepare('SELECT 1 FROM school_memberships a JOIN school_memberships b ON b.school_id=a.school_id WHERE a.user_id=? AND b.user_id=?');$q->execute([$actor,$id]);if(!$q->fetchColumn()){http_response_code(403);exit('This account is outside your team access.');}}
$schoolsAdded=0;$adminsAdded=0;if(in_array($user['role'],['admin','sub_admin'],true)){$q=$db->prepare("SELECT COUNT(*) FROM audit_logs WHERE actor_id=? AND action='create' AND entity_type='school'");$q->execute([$id]);$schoolsAdded=(int)$q->fetchColumn();}if($user['role']==='sub_admin'){$q=$db->prepare("SELECT COUNT(*) FROM audit_logs WHERE actor_id=? AND action='create' AND entity_type='user' AND JSON_UNQUOTE(JSON_EXTRACT(details,'$.role'))='admin'");$q->execute([$id]);$adminsAdded=(int)$q->fetchColumn();}$q=$db->prepare('SELECT s.name FROM school_memberships m JOIN schools s ON s.id=m.school_id WHERE m.user_id=? ORDER BY s.name');$q->execute([$id]);$schools=$q->fetchAll(PDO::FETCH_COLUMN);$q=$db->prepare("SELECT l.id,l.action,l.entity_type,l.entity_id,l.details,l.created_at,a.name actor_name FROM audit_logs l LEFT JOIN users a ON a.id=l.actor_id WHERE l.actor_id=? OR (l.entity_type='user' AND l.entity_id=?) ORDER BY l.created_at DESC");$q->execute([$id,$id]);$userAudit=$q->fetchAll();$options=['admin'=>['Add school directors','Help a director register a school'],'sub_admin'=>['Perform delegated system administration','Add admins and directors within delegated scope'],'director'=>['Register owned schools','Create school departments and add team members'],'sub_director'=>['Manage only schools assigned by the director'],'headteacher'=>['Register pupils','Delegate academic and examination responsibilities']];?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Role analysis · ShuleLite</title><link rel="stylesheet" href="assets/app.css"></head><body><main class="auth-page"><section class="auth-shell"><a class="brand" href="team.php"><span class="brand-mark">S</span><span>shule<span class="brand-lite">lite</span></span></a><div class="auth-card"><div class="eyebrow">ROLE ANALYSIS</div><h1><?=e($user['name'])?></h1><p class="muted"><?=e($user['email']?:($user['username']??'Username account'))?> · <?=e($user['status'])?></p><div class="metric-grid"><article class="metric-card"><div class="metric-label">ROLE</div><div class="metric-value metric-role"><?=e(str_replace('_',' ',$user['role']))?></div><div class="metric-note">Created <?=e(date('j M Y',strtotime($user['created_at'])))?></div></article><?php if(in_array($user['role'],['admin','sub_admin'],true)):?><article class="metric-card"><div class="metric-label">SCHOOLS CREATED</div><div class="metric-value"><?=$schoolsAdded?></div><div class="metric-note">Records this user specifically added</div></article><?php endif;?><?php if($user['role']==='sub_admin'):?><article class="metric-card"><div class="metric-label">ADMINS CREATED</div><div class="metric-value"><?=$adminsAdded?></div><div class="metric-note">Admin accounts this user added</div></article><?php endif;?></div><?php if($role==='system_admin'&&$user['role']==='sub_admin'):?><section class="note-create"><h2>Sub System Admin status</h2><p class="muted">Change whether this account can sign in and use its assigned system role.</p><?php if(isset($_GET['status_changed'])):?><div class="notice success" role="status">Sub System Admin status updated.</div><?php endif;?><form method="post" onsubmit="return confirm('<?= $user['status']==='active'?'Deactivate':'Activate' ?> this Sub System Admin role?')"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><button class="button <?= $user['status']==='active'?'danger':'primary' ?>" type="submit"><?= $user['status']==='active'?'Deactivate role':'Activate role' ?></button></form></section><?php endif;?><section class="note-create user-audit"><div class="section-heading"><div><div class="eyebrow">ACCOUNT ACTIVITY</div><h2>Audit log</h2></div><span class="count-pill"><?=count($userAudit)?> events</span></div><?php if(!$userAudit):?><div class="empty-state"><h3>No audit activity</h3><p>Actions performed by or recorded against this user will appear here.</p></div><?php else:?><div class="table-wrap"><table><thead><tr><th>Date and time</th><th>Actor</th><th>Action</th><th>Record</th><th>Details</th></tr></thead><tbody><?php foreach($userAudit as $log):?><tr><td><?=e(date('j M Y H:i',strtotime($log['created_at'])))?></td><td><?=e($log['actor_name']?:'Deleted account')?></td><td><span class="audit-action"><?=e(ucfirst(str_replace('_',' ',$log['action'])))?></span></td><td><?=e(str_replace('_',' ',$log['entity_type']))?> #<?=e((string)($log['entity_id']??'—'))?></td><td><?=e($log['details']??'—')?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section><h2>Role options</h2><?php if(isset($options[$user['role']])):?><ul><?php foreach($options[$user['role']] as $option):?><li><?=e($option)?></li><?php endforeach;?></ul><?php else:?><p class="muted">Role-specific options are managed through the user’s school assignments.</p><?php endif;?><p><strong>School access:</strong> <?=e($schools?implode(', ',$schools):'System wide')?></p><a class="button primary full" href="team.php">Back to Team</a></div></section></main></body></html>
